// Lista de códigos para temporada de verano
const CODES = SEASON_CODES_TEMPORADA_VERANO;

// Función para sanitizar códigos al guardar
const sanitizeCode = (code: string) => {
  return code.toLowerCase().replace(/[/.#$[\]]/g, '-');
};

// Función para desanitizar códigos al mostrar
const desanitizeCode = (code: string) => {
  return CODES.find(originalCode => sanitizeCode(originalCode) === code) || code;
};

interface ItemState {
  completed: boolean;
  hasStock: boolean;
  lastUpdated?: number;
}

interface ChecklistEntry {
  code: string;
  mes: string;
  semana: string;
  periodKey?: string;
  sinAjuste1A?: boolean;
  description?: string;
  family?: ChecklistFamily;
}

type ChecklistViewFilter = 'pending' | 'completed' | 'noStock' | 'all';

type ChecklistFamily = 'TF' | 'TV' | 'SI' | 'OT' | 'OTROS';
const getChecklistFamily = (code: string): ChecklistFamily => {
  if (code.startsWith('TF')) return 'TF';
  if (code.startsWith('TV')) return 'TV';
  if (code.startsWith('SI')) return 'SI';
  if (code.startsWith('OT')) return 'OT';
  return 'OTROS';
};
const checklistFamilyLabel: Record<ChecklistFamily, string> = { TF: 'TF', TV: 'TV', SI: 'SI', OT: 'OT · Máquinas y moldes', OTROS: 'OTROS' };

type PreviewFamilyItem = readonly [branch: string, family: ChecklistFamily, code: string, sinAjuste1A: boolean, description: string];

