const buildFallbackEntries = (codes: string[]): ChecklistEntry[] => codes.map((code) => ({ code, mes: '', semana: '' }));

const getLocalItemState = (localItems: Record<string, ItemState>, code: string, periodKey?: string): ItemState => {
  const key = getChecklistEntryKey(code, periodKey);
  return localItems[key] || { completed: false, hasStock: true };
};

const MOTIVATION_MESSAGES = {
  20: {
    title: "¡Excelente inicio! 🌟",
    description: "¡Sigue así, vas por buen camino!",
    variant: "success" as const
  },
  40: {
    title: "¡Vas muy bien! 💪",
    description: "¡Ya llevas casi la mitad!",
    variant: "success" as const
  },
  60: {
    title: "¡Increíble progreso! 🚀",
    description: "¡Mantén ese ritmo!",
    variant: "success" as const
  },
  80: {
    title: "¡Casi llegas! 🎯",
    description: "¡Te falta muy poco!",
    variant: "success" as const
  },
  100: {
    title: "¡FELICITACIONES! 🎉",
    description: "¡Has completado todos los ítems!",
    variant: "success" as const
  }
};

const celebrateProgress = (progress: number) => {
  
  
  const defaults = {
    spread: 360,
    ticks: 100,
    gravity: 0,
    decay: 0.94,
    startVelocity: 30,
  };

  const particleCount = Math.floor(progress * 2);

  if (progress >= 20) {
    confetti({
      ...defaults,
      particleCount,
      colors: ['#ffd700', '#ff0000'],
      origin: { x: 0.2, y: 0.8 }
    });
    confetti({
      ...defaults,
      particleCount,
      colors: ['#ffd700', '#ff0000'],
      origin: { x: 0.8, y: 0.8 }
    });
  }

  if (progress >= 40) {
    confetti({
      ...defaults,
      particleCount,
      angle: 60,
      spread: 80,
      colors: ['#00ff00', '#0000ff'],
      origin: { x: 0, y: 0.8 }
    });
    confetti({
      ...defaults,
      particleCount,
      angle: 120,
      spread: 80,
      colors: ['#00ff00', '#0000ff'],
      origin: { x: 1, y: 0.8 }
    });
  }

  if (progress >= 60) {
    const duration = 1500;
    const end = Date.now() + duration;

    const frame = () => {
      confetti({
        ...defaults,
        particleCount: 2,
        angle: 60,
        spread: 55,
        origin: { x: 0, y: 0.5 }
      });
      confetti({
        ...defaults,
        particleCount: 2,
        angle: 120,
        spread: 55,
        origin: { x: 1, y: 0.5 }
      });

      if (Date.now() < end) {
        requestAnimationFrame(frame);
      }
    };
    frame();
  }

  if (progress >= 80) {
    const circles = 3;
    for (let i = 0; i < circles; i++) {
      setTimeout(() => {
        confetti({
          ...defaults,
          particleCount: 100,
          angle: 360 * i / circles,
          spread: 360 / circles,
          colors: ['#ff00ff', '#00ffff', '#ffff00'],
          origin: { x: 0.5, y: 0.5 }
        });
      }, i * 200);
    }
  }

  if (progress === 100) {
    const duration = 2000;
    const end = Date.now() + duration;

    const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];

    (function frame() {
      confetti({
        ...defaults,
        particleCount: 6,
        angle: 60,
        spread: 360,
        colors,
        origin: { x: Math.random(), y: Math.random() * 0.8 }
      });
      confetti({
        ...defaults,
        particleCount: 6,
        angle: 120,
        spread: 360,
        colors,
        origin: { x: Math.random(), y: Math.random() * 0.8 }
      });

      if (Date.now() < end) {
        requestAnimationFrame(frame);
      }
    }());
  }
};

export default function Home() {
  const [selectedBranch, setSelectedBranch] = useState<Branch>();
  const [items, setItems] = useState<Record<string, ItemState>>({});
  const [loading, setLoading] = useState(false);
  const [expandedSemanas, setExpandedSemanas] = useState<Set<string>>(new Set());
  const [searchFilter, setSearchFilter] = useState('');
  const [checklistViewFilter, setChecklistViewFilter] = useState<ChecklistViewFilter>('pending');
  const [openChecklistFamily, setOpenChecklistFamily] = useState<ChecklistFamily | null>(null);
  const [showHistoricalMonths, setShowHistoricalMonths] = useState(false);
  const [celebratedMonths, setCelebratedMonths] = useState<Set<string>>(new Set());
  const previousMonthCompletion = useRef<Record<string, boolean>>({});
  const [addedItems, setAddedItems] = useState<Record<string, { code: string; addedAt: number; month?: string }>>({});
  const [newItemCode, setNewItemCode] = useState('');

  const currentMonth = useMemo(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  }, []);

  const currentCalendarMonth = useMemo(() => getMesActualCalendario(), []);

  const currentMonthAddedItems = useMemo(() => {
    return Object.fromEntries(
      Object.entries(addedItems).filter(([_, item]) => {
        if (!item.month) {
          const d = new Date(item.addedAt);
          return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}` === currentMonth;
        }
        return item.month === currentMonth;
      })
    );
  }, [addedItems, currentMonth]);

  const { toast } = useToast();
  const isFirebaseReadOnly = import.meta.env.VITE_FIREBASE_READONLY === 'true';
  const [lastToastProgress, setLastToastProgress] = useState(0);
  const [showScrollButton, setShowScrollButton] = useState(false);
  const { data: branchesData } = useFirebaseData();

  const { data: ultimaActualizacion } = useQuery<{ costos_fecha: string; ventas_fecha: string }>({
    queryKey: ['/api/ultima-actualizacion'],
    queryFn: async () => {
      const response = await fetch('/api/ultima-actualizacion');
      if (!response.ok) throw new Error('Error');
      return response.json();
    },
    refetchInterval: 300000,
  });

  useEffect(() => {
    if (!selectedBranch || !branchesData) return;
    const branchData = branchesData.find(b => b.id === selectedBranch);
    if (branchData?.addedItems) {
      setAddedItems(branchData.addedItems);
    }
  }, [branchesData, selectedBranch]);

  useEffect(() => {
    if (!selectedBranch || !branchesData || loading) return;

    const branchData = branchesData.find(b => b.id === selectedBranch);
    if (!branchData) return;

    const calendario = getCalendarioSucursal(selectedBranch);
    const entriesToUse = calendario ? getAllChecklistEntries(calendario) : buildFallbackEntries(CODES);

    const newItems = entriesToUse.reduce((acc, entry) => {
      const itemKey = getChecklistEntryKey(entry.code, entry.periodKey);
      const existingItem = getChecklistItemState(branchData, entry.code, entry.periodKey);
      acc[itemKey] = existingItem
        ? {
            completed: existingItem.completed === true,
            hasStock: existingItem.hasStock !== false,
            lastUpdated: existingItem.lastUpdated,
          }
        : { completed: false, hasStock: true };
      return acc;
    }, {} as Record<string, ItemState>);

    const currentKeys = Object.keys(items);
    const nextKeys = Object.keys(newItems);
    const hasChanges = currentKeys.length !== nextKeys.length || nextKeys.some((key) => {
      const current = items[key];
      const updated = newItems[key];
      return !current || current.completed !== updated.completed || current.hasStock !== updated.hasStock;
    });

    if (hasChanges) {
      setItems(newItems);
    }
  }, [branchesData, selectedBranch, loading, items]);

  // Obtener calendario semanal si existe para la sucursal
  const calendarioSemanal = selectedBranch ? getCalendarioSucursal(selectedBranch) : null;
  const semanaActual = getSemanaActual();

  const allChecklistEntries = useMemo(() => {
    return calendarioSemanal ? getAllChecklistEntries(calendarioSemanal) : buildFallbackEntries(CODES);
  }, [calendarioSemanal]);

  const activeChecklistEntries = useMemo(() => {
    if (!calendarioSemanal) return buildFallbackEntries(CODES);
    const currentMonthEntries = getChecklistEntriesForMonth(calendarioSemanal, currentCalendarMonth);
    return currentMonthEntries.length > 0 ? currentMonthEntries : getAllChecklistEntries(calendarioSemanal);
  }, [calendarioSemanal, currentCalendarMonth]);

  // Calcular progreso por semana
  const progresoSemanal = useMemo(() => {
    if (!calendarioSemanal || Object.keys(items).length === 0) return [];

    return calendarioSemanal.semanas.map(semana => {
      const completados = semana.items.filter(code => isChecklistCompleted(getLocalItemState(items, code, semana.periodKey))).length;
      const total = semana.items.length;
      const porcentaje = total > 0 ? (completados / total) * 100 : 0;
      const esActual = semanaActual?.mes === semana.mes && semanaActual?.semana === semana.semana;

      return {
        ...semana,
        completados,
        total,
        porcentaje,
        esActual
      };
    });
  }, [calendarioSemanal, items, semanaActual]);

  // Toggle expandir/colapsar semana
  const toggleSemana = (key: string) => {
    setExpandedSemanas(prev => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  };

  // Calcular progreso por mes para detectar objetivos cumplidos
  const progresoMensual = useMemo(() => {
    if (!calendarioSemanal) return [];

    const meses = Array.from(new Set(calendarioSemanal.semanas.map((semana) => semana.mes)));
    return meses.map((mes) => {
      const entries = getChecklistEntriesForMonth(calendarioSemanal, mes);
      const completados = entries.filter((entry) => isChecklistCompleted(getLocalItemState(items, entry.code, entry.periodKey))).length;
      return {
        mes,
        objetivo: entries.length,
        completados,
        cumplido: completados >= entries.length && entries.length > 0,
      };
    });
  }, [calendarioSemanal, items]);

  // Detectar cuando se cumple un objetivo mensual y celebrar
  useEffect(() => {
    if (loading || !selectedBranch || !progresoMensual.length) return;
    
    progresoMensual.forEach(({ mes, cumplido }) => {
      const completionKey = `${selectedBranch}:${mes}`;
      const wasComplete = previousMonthCompletion.current[completionKey];
      if (cumplido && wasComplete === false && !celebratedMonths.has(completionKey)) {
        // Marcar como celebrado
        setCelebratedMonths(prev => new Set(Array.from(prev).concat(completionKey)));
        
        // Mostrar confetti
        celebrateProgress(100);
        
        // Mostrar toast de felicitación
        toast({
          title: `🏆 ¡Objetivo ${mes} cumplido!`,
          description: `¡Excelente trabajo! Has completado todos los ítems del mes de ${mes}.`,
          duration: 5000,
        });
      }
      previousMonthCompletion.current[completionKey] = cumplido;
    });
  }, [progresoMensual, celebratedMonths, loading, selectedBranch, toast]);

  useEffect(() => {
    const handleScroll = () => {
      setShowScrollButton(window.pageYOffset > 100);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    analytics.logPageView('home');
    const startTime = Date.now();
    
    return () => {
      const duration = (Date.now() - startTime) / 1000;
      analytics.logSessionDuration(duration);
    };
  }, []);

  const loadBranchData = async (branch: Branch) => {
    if (loading) return;

    setLoading(true);
    setSelectedBranch(branch);

    try {
      const branchData = branchesData?.find(b => b.id === branch);
      const calendario = getCalendarioSucursal(branch);
      const entriesToUse = calendario ? getAllChecklistEntries(calendario) : buildFallbackEntries(CODES);

      const initializedItems = entriesToUse.reduce((acc, entry) => {
        const itemKey = getChecklistEntryKey(entry.code, entry.periodKey);
        const existingItem = branchData ? getChecklistItemState(branchData, entry.code, entry.periodKey) : null;

        acc[itemKey] = existingItem
          ? {
              completed: existingItem.completed === true,
              hasStock: existingItem.hasStock !== false,
              lastUpdated: existingItem.lastUpdated,
            }
          : { completed: false, hasStock: true };
        return acc;
      }, {} as Record<string, ItemState>);

      setItems(initializedItems);
      setAddedItems(branchData?.addedItems || {});
      analytics.logAction('branch_select', { branch });

      if (branchData?.totalCompleted) {
        const progress = Math.floor(branchData.totalCompleted);
        setLastToastProgress(progress);
      } else {
        setLastToastProgress(0);
      }
    } catch (error) {
      console.error("Error al cargar datos:", error);
      toast({
        title: "Error de conexión",
        description: "No se pudieron cargar los datos. Intente nuevamente.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleToggle = async (code: string, field: keyof ItemState, periodKey?: string) => {
    if (!selectedBranch || loading) return;
    if (isFirebaseReadOnly) {
      toast({
        title: 'Modo solo lectura',
        description: 'La visual local está conectada a Firebase real en modo lectura. No se guardan cambios.',
      });
      return;
    }

    const itemKey = getChecklistEntryKey(code, periodKey);

    const newItems = {
      ...items,
      [itemKey]: {
        ...(items[itemKey] || { completed: false, hasStock: true }),
        [field]: !items[itemKey]?.[field],
        ...(field === 'completed'
          ? { hasStock: true }
          : field === 'hasStock'
            ? { completed: !items[itemKey]?.hasStock }
            : {}
        )
      }
    };

    setItems(newItems);

    try {
      const totalItemsActivos = activeChecklistEntries.length > 0 ? activeChecklistEntries.length : CODES.length;
      const completedCount = activeChecklistEntries.filter((entry) => isChecklistCompleted(getLocalItemState(newItems, entry.code, entry.periodKey))).length;
      const noStockCount = activeChecklistEntries.filter((entry) => isChecklistNoStock(getLocalItemState(newItems, entry.code, entry.periodKey))).length;
      const completedPercentage = totalItemsActivos > 0 ? Math.round((completedCount / totalItemsActivos) * 100) : 0;

      for (const [threshold, message] of Object.entries(MOTIVATION_MESSAGES)) {
        const thresholdNum = parseInt(threshold);

        if (completedPercentage >= thresholdNum && lastToastProgress < thresholdNum) {
          toast({
            title: message.title,
            description: `${message.description} - ${completedPercentage}% completado`,
            variant: "success",
            duration: 5000,
          });

          setLastToastProgress(thresholdNum);
          celebrateProgress(thresholdNum);
          break;
        }
      }

      await storage.updateChecklistItem(selectedBranch, code, {
        completed: newItems[itemKey]?.completed === true,
        hasStock: newItems[itemKey]?.hasStock !== false,
        periodKey,
      });

      analytics.logAction('item_toggle', {
        branch: selectedBranch,
        code: itemKey,
        field,
        newValue: !items[itemKey]?.[field]
      });
    } catch (error) {
      console.error("Error al guardar:", error);
      setItems(items);
      toast({
        title: "Error al guardar",
        description: "Intente nuevamente",
        variant: "destructive",
        duration: 5000,
      });
    }
  };

  const handleAddItem = async () => {
    if (isFirebaseReadOnly) {
      toast({ title: 'Modo solo lectura', description: 'No se pueden agregar artículos en esta sesión local.' });
      return;
    }
    if (!selectedBranch || !newItemCode.trim()) return;
    const code = newItemCode.trim().toUpperCase();
    const key = sanitizeCode(code);
    if (currentMonthAddedItems[key]) {
      toast({ title: "Ya existe", description: `El ítem ${code} ya fue agregado este mes.`, variant: "destructive" });
      return;
    }
    const now = new Date();
    const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const newAddedItems = { ...addedItems, [key]: { code, addedAt: Date.now(), month: currentMonth } };
    setAddedItems(newAddedItems);
    setNewItemCode('');
    try {
      await storage.updateBranch(selectedBranch, { addedItems: newAddedItems });
      toast({ title: "Ítem agregado", description: `${code} fue agregado a la lista.` });
    } catch (error) {
      setAddedItems(addedItems);
      toast({ title: "Error", description: "No se pudo guardar.", variant: "destructive" });
    }
  };

  const handleRemoveAddedItem = async (key: string) => {
    if (isFirebaseReadOnly) {
      toast({ title: 'Modo solo lectura', description: 'No se pueden eliminar artículos en esta sesión local.' });
      return;
    }
    if (!selectedBranch) return;
    const { [key]: _, ...rest } = addedItems;
    setAddedItems(rest);
    try {
      await storage.updateBranch(selectedBranch, { addedItems: Object.keys(rest).length > 0 ? rest : {} });
    } catch (error) {
      setAddedItems(addedItems);
      toast({ title: "Error", description: "No se pudo eliminar.", variant: "destructive" });
    }
  };

  const progress = useMemo(() => {
    if (!selectedBranch || Object.keys(items).length === 0) {
      return { completed: 0, noStock: 0, completedCount: 0, totalItems: 0 };
    }

    let totalItems: number;
    let completedCount: number;
    let noStockCount: number;

    if (calendarioSemanal) {
      totalItems = activeChecklistEntries.length;
      completedCount = activeChecklistEntries.filter((entry) => isChecklistCompleted(getLocalItemState(items, entry.code, entry.periodKey))).length;
      noStockCount = activeChecklistEntries.filter((entry) => isChecklistNoStock(getLocalItemState(items, entry.code, entry.periodKey))).length;
    } else {
      totalItems = CODES.length;
      completedCount = Math.min(Object.values(items).filter(isChecklistCompleted).length, totalItems);
      noStockCount = Object.values(items).filter(isChecklistNoStock).length;
    }

    const completedPercentage = totalItems > 0 ? (completedCount / totalItems) * 100 : 0;
    const noStockPercentage = totalItems > 0 ? (noStockCount / totalItems) * 100 : 0;

    return {
      completed: completedPercentage,
      noStock: noStockPercentage,
      completedCount,
      totalItems
    };
  }, [selectedBranch, items, calendarioSemanal, activeChecklistEntries]);

  const checklistFilterLabels: Record<ChecklistViewFilter, string> = {
    pending: 'Pendientes',
    completed: 'Completados',
    noStock: 'Sin Stock',
    all: 'Todos',
  };

  const previewFamilyEntries = useMemo(() => PREVIEW_FAMILIAS_COMPLETAS
    .filter(([branch]) => branch === selectedBranch)
    .map(([, family, code, sinAjuste1A, description]) => ({
      code,
      mes: '',
      semana: '',
      family,
      sinAjuste1A,
      description,
    })), [selectedBranch]);

  const checklistSourceEntries = useMemo(() => {
    if (previewFamilyEntries.length > 0) return previewFamilyEntries;
    return activeChecklistEntries.length > 0 ? activeChecklistEntries : buildFallbackEntries(CODES);
  }, [activeChecklistEntries, previewFamilyEntries]);

  const checklistSummary = useMemo(() => {
    const total = checklistSourceEntries.length;
    const completed = checklistSourceEntries.filter((entry) => isChecklistCompleted(getLocalItemState(items, entry.code, entry.periodKey))).length;
    const noStock = checklistSourceEntries.filter((entry) => isChecklistNoStock(getLocalItemState(items, entry.code, entry.periodKey))).length;
    const pending = checklistSourceEntries.filter((entry) => {
      const state = getLocalItemState(items, entry.code, entry.periodKey);
      return isChecklistPending(state);
    }).length;

    return { pending, completed, noStock, total };
  }, [checklistSourceEntries, items]);

  const visibleChecklistEntries = useMemo(() => {
    const normalizedSearch = searchFilter.trim().toLowerCase();
    let entries = [...checklistSourceEntries];

    if (checklistViewFilter === 'pending') {
      const rankEntry = (entry: ChecklistEntry) => {
        const state = getLocalItemState(items, entry.code, entry.periodKey);
        if (isChecklistCompleted(state)) return 2;
        if (isChecklistNoStock(state)) return 1;
        return 0;
      };
      entries.sort((a, b) => rankEntry(a) - rankEntry(b));
    } else if (checklistViewFilter === 'completed') {
      entries = entries.filter((entry) => isChecklistCompleted(getLocalItemState(items, entry.code, entry.periodKey)));
    } else if (checklistViewFilter === 'noStock') {
      entries = entries.filter((entry) => isChecklistNoStock(getLocalItemState(items, entry.code, entry.periodKey)));
    }

    if (!normalizedSearch) return entries;

    return entries.filter((entry) => {
      const code = entry.code.toLowerCase();
      const displayCode = getChecklistDisplayCode(entry.code).toLowerCase();
      return code.includes(normalizedSearch) || displayCode.includes(normalizedSearch) || entry.description?.toLowerCase().includes(normalizedSearch) === true;
    });
  }, [checklistSourceEntries, checklistViewFilter, searchFilter, items]);

  const checklistFamilies = useMemo(() => {
    const familyOrder: ChecklistFamily[] = ['TF', 'TV', 'SI', 'OT', 'OTROS'];
    return familyOrder.map((family) => {
      const allEntries = checklistSourceEntries.filter((entry) => (entry.family ?? getChecklistFamily(entry.code)) === family);
      const visibleEntries = visibleChecklistEntries.filter((entry) => (entry.family ?? getChecklistFamily(entry.code)) === family);
      const completed = allEntries.filter((entry) => isChecklistCompleted(getLocalItemState(items, entry.code, entry.periodKey))).length;
      const noStock = allEntries.filter((entry) => isChecklistNoStock(getLocalItemState(items, entry.code, entry.periodKey))).length;
      return { family, allEntries, visibleEntries, completed, noStock };
    }).filter((group) => group.allEntries.length > 0);
  }, [checklistSourceEntries, visibleChecklistEntries, items]);

  const searchOpenFamily = searchFilter.trim()
    ? checklistFamilies.find((group) => group.visibleEntries.length > 0)?.family ?? null
    : null;

  return (
    <div className="space-y-4 sm:space-y-8">
      <div className="flex flex-col gap-3 sm:gap-4 md:flex-row md:items-center justify-between bg-background pt-2 sm:pt-4 pb-2 sm:pb-4">
        <div className="flex flex-wrap items-center gap-2 sm:gap-4">
          {selectedBranch && (
            <Button
              variant="outline"
              onClick={() => {
                setSelectedBranch(undefined);
                setItems({});
                setAddedItems({});
                setLastToastProgress(0);
              }}
              size="sm"
              className="gap-2 w-full sm:w-auto bg-primary/5 hover:bg-primary/10 border-primary/20 hover:border-primary/30 shadow-lg hover:shadow-xl transition-all duration-300 hover:scale-105"
            >
              <ArrowLeft className="h-4 w-4 text-primary" />
              Volver al Dashboard
            </Button>
          )}
          
          {!selectedBranch && (
            <BranchSelector
              value={selectedBranch}
              onChange={loadBranchData}
            />
          )}
          


        </div>
        {/* Fecha actualización - mobile: fija arriba, chica | desktop: normal */}
        {ultimaActualizacion && (
          <>
            {/* Mobile: barra fija arriba debajo del header */}
            <div className="sm:hidden fixed top-14 left-0 right-0 z-40 bg-muted/80 backdrop-blur-sm border-b px-2 py-1 flex items-center justify-center gap-1.5">
              <Clock className="h-3 w-3 text-muted-foreground shrink-0" />
              <span className="text-[10px] text-muted-foreground">Act:</span>
              <span className="text-[10px] font-semibold">
                {(() => {
                  const parseLocalDate = (str: string) => {
                    if (!str) return null;
                    if (str.includes(' ')) {
                      const [datePart, timePart] = str.split(' ');
                      const [y, m, d] = datePart.split('-').map(Number);
                      const [h, min] = timePart.split(':').map(Number);
                      return { date: new Date(y, m - 1, d, h, min), hasTime: true };
                    }
                    const [y, m, d] = str.split('-').map(Number);
                    return { date: new Date(y, m - 1, d), hasTime: false };
                  };
                  const costo = parseLocalDate(ultimaActualizacion.costos_fecha);
                  const venta = parseLocalDate(ultimaActualizacion.ventas_fecha);
                  const latest = costo && venta ? (costo.date > venta.date ? costo : venta) : costo || venta;
                  if (!latest) return 'Sin datos';
                  const d = latest.date;
                  const timeStr = latest.hasTime ? ` ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}` : '';
                  return `${d.getDate()}/${d.getMonth() + 1}/${String(d.getFullYear()).slice(2)}${timeStr}`;
                })()}
              </span>
            </div>
            {/* Desktop: bloque normal */}
            <div className="hidden sm:flex items-center gap-2 bg-muted/50 rounded-lg px-3 py-1.5 border w-full md:w-auto">
              <Clock className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
              <div className="flex flex-col">
                <span className="text-sm font-semibold leading-tight">
                  {(() => {
                    const parseLocalDate = (str: string) => {
                      if (!str) return null;
                      if (str.includes(' ')) {
                        const [datePart, timePart] = str.split(' ');
                        const [y, m, d] = datePart.split('-').map(Number);
                        const [h, min] = timePart.split(':').map(Number);
                        return { date: new Date(y, m - 1, d, h, min), hasTime: true };
                      }
                      const [y, m, d] = str.split('-').map(Number);
                      return { date: new Date(y, m - 1, d), hasTime: false };
                    };
                    const costo = parseLocalDate(ultimaActualizacion.costos_fecha);
                    const venta = parseLocalDate(ultimaActualizacion.ventas_fecha);
                    const latest = costo && venta ? (costo.date > venta.date ? costo : venta) : costo || venta;
                    if (!latest) return 'Sin datos';
                    const d = latest.date;
                    const timeStr = latest.hasTime ? ` ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}` : '';
                    return `${d.getDate()}/${d.getMonth() + 1}/${String(d.getFullYear()).slice(2)}${timeStr}`;
                  })()}
                </span>
                <span className="text-[10px] text-muted-foreground leading-tight">Última actualización</span>
                <span className="text-[9px] text-muted-foreground/70 leading-tight">Actualización automática: Lun, Mié, Vie</span>
              </div>
            </div>
          </>
        )}
      </div>

      {loading ? (
        <div className="flex items-center justify-center p-8">
          <LoadingMascot message="Actualizando datos..." />
        </div>
      ) : selectedBranch ? (
        <div>
          <Card>
            <CardHeader className="px-4 py-2.5 sm:px-6 sm:py-4">
              <CardTitle className="flex flex-wrap items-center gap-2 text-lg sm:text-xl">
                <span className="sm:hidden">{selectedBranch}</span>
                <span className="hidden sm:inline">Checklist de {selectedBranch}</span>
                {progress.completed === 100 && <Trophy className="h-5 w-5 text-yellow-500" />}
              </CardTitle>
              <p className="mt-0.5 text-xs font-medium text-slate-500 sm:hidden">Checklist · {currentCalendarMonth.charAt(0)}{currentCalendarMonth.slice(1).toLowerCase()}</p>
            </CardHeader>
            <CardContent className="space-y-3 px-4 pb-4 sm:space-y-4 sm:px-6 sm:pb-6">
              {/* Calendario con objetivos mensuales para T.Mendoza */}
              {(
                <div className="space-y-2.5 sm:space-y-3">
                  {/* Encabezado con título */}
                  <div className="hidden rounded-md border border-amber-200/80 bg-amber-50/70 px-2.5 py-1.5 sm:block sm:px-3 sm:py-2" data-testid="header-calendario">
                    <h3 className="text-sm font-semibold leading-tight text-slate-800 sm:text-base">{activeChecklistEntries.length} Artículos solicitados para realizar inventario</h3>
                    <p className="mt-0.5 text-xs leading-tight text-slate-500 sm:mt-1 sm:text-sm">Selecciona los ítems que vayas completando - {selectedBranch}</p>
                  </div>
                  {/* Objetivos mensuales - el usuario elige cuáles items completar */}
                  {(() => {
                    const todosLosCodigos = activeChecklistEntries;
                    const itemsCompletados = todosLosCodigos.filter(entry => isChecklistCompleted(getLocalItemState(items, entry.code, entry.periodKey)));
                    const totalCompletados = itemsCompletados.length;
                    const totalSinStock = todosLosCodigos.filter(entry => isChecklistNoStock(getLocalItemState(items, entry.code, entry.periodKey))).length;
                    const objetivosMensuales = progresoMensual;
                    const mesesOperativos = objetivosMensuales.filter(({ mes }) => ['OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'].includes(mes));
                    const mesesHistoricos = objetivosMensuales.filter(({ mes }) => !['OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'].includes(mes));
                    const mesesProximos = mesesOperativos.filter(({ mes }) => mes !== currentCalendarMonth);
                    const mesCorto = (mes: string) => `${mes.slice(0, 1)}${mes.slice(1, 3).toLowerCase()}`;
                    
                    return (
                      <>
                        {/* Secci?n fija: objetivos y progreso */}
                        <div className="space-y-2 pb-1 pt-0.5 sm:space-y-2.5 sm:pb-2 sm:pt-1">
                        {mesesHistoricos.length > 0 && (
                          <div className="rounded-md border border-slate-200 bg-slate-50 px-2.5 py-2 text-xs sm:px-3">
                            <div className="flex items-center justify-between gap-2">
                              <span className="font-medium text-slate-700 sm:hidden">Historial · {mesesHistoricos.length} meses</span>
                              <span className="hidden font-medium text-slate-700 sm:inline">Historial anterior</span>
                              <button
                                type="button"
                                onClick={() => setShowHistoricalMonths((visible) => !visible)}
                                className="shrink-0 font-medium text-primary hover:underline"
                              >
                                {showHistoricalMonths ? 'Ocultar historial ▴' : 'Ver historial ▾'}
                              </button>
                            </div>
                            <div className="mt-1 hidden flex-wrap gap-x-2 gap-y-1 text-slate-600 sm:flex">
                              {mesesHistoricos.map(({ mes, objetivo, completados, cumplido }) => (
                                <span key={mes}>{mesCorto(mes)} {cumplido ? '✓' : `${completados}/${objetivo}`}</span>
                              ))}
                            </div>
                            {showHistoricalMonths && (
                              <div className="mt-2 grid grid-cols-2 gap-1 border-t border-slate-200 pt-2 text-[11px] sm:grid-cols-3 md:grid-cols-6">
                                {mesesHistoricos.map(({ mes, objetivo, completados, cumplido }) => (
                                  <span key={`detalle-${mes}`} className="rounded bg-white px-1.5 py-1">{mes}: {completados}/{objetivo}{cumplido ? ' ✓' : ''}</span>
                                ))}
                              </div>
                            )}
                          </div>
                        )}
                        {/* Resumen de objetivos por mes */}
                        <div className="grid grid-cols-1 items-start gap-1.5 sm:grid-cols-3 sm:gap-2.5" data-testid="objetivos-mensuales">
                          {mesesOperativos.map(({ mes, objetivo, completados: completadosParaEsteMes, cumplido: mesCompleto }) => {
                            const porcentajeMes = objetivo > 0 ? (completadosParaEsteMes / objetivo) * 100 : 0;
                            const esPeriodoActual = mes === currentCalendarMonth;
                            
                            return (
                              <div 
                                key={mes}
                                onClick={() => {
                                  const element = document.getElementById(`items-lista`);
                                  if (element) {
                                    element.scrollIntoView({ behavior: 'smooth', block: 'start' });
                                  }
                                }}
                                className={`relative min-w-0 self-start cursor-pointer overflow-hidden rounded-md border p-2 transition-colors hover:border-slate-300 sm:p-2.5 ${!esPeriodoActual ? 'hidden sm:block' : ''} ${
                                  esPeriodoActual ? 'border-emerald-300 bg-white shadow-sm' :
                                  mesCompleto ? 'border-emerald-200 bg-white' :
                                  'border-slate-200 bg-slate-50/60'
                                }`}
                              >
                                {mesCompleto ? (
                                  <>
                                    <div className="sm:hidden flex items-center justify-between gap-1">
                                      <div className="flex items-center gap-1">
                                        <CheckCircle2 className="h-3.5 w-3.5 text-green-600 shrink-0" />
                                        <span className="font-bold text-xs text-green-700">{mes}</span>
                                      </div>
                                      <span className="text-[10px] text-green-600 font-medium">{completadosParaEsteMes}/{objetivo}</span>
                                    </div>
                                    <Progress value={porcentajeMes} className="h-1.5 mt-1 sm:hidden [&>div]:bg-green-500" />
                                    <div className="hidden sm:block">
                                      <div className="absolute -top-1 -right-1 bg-green-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-bl-lg rounded-tr-lg shadow">
                                        ✓ CUMPLIDO
                                      </div>
                                      <div className="text-xs text-slate-500">Objetivo: {objetivo} items</div>
                                      <div className="font-semibold text-base text-emerald-700">{mes}</div>
                                      <div className="text-sm flex items-center gap-1">
                                        <span className="text-xl font-bold text-green-600">{completadosParaEsteMes}</span>
                                        <span className="text-gray-400">/ {objetivo}</span>
                                        <Trophy className="h-5 w-5 text-yellow-500 ml-1" />
                                      </div>
                                      <Progress value={porcentajeMes} className="h-2 mt-2 [&>div]:bg-green-500" />
                                      <div className="text-xs text-green-600 font-medium mt-1 flex items-center gap-1">
                                        <PartyPopper className="h-3 w-3" /> ¡Meta alcanzada!
                                      </div>
                                    </div>
                                  </>
                                ) : (
                                  <>
                                    <div className="text-[10px] sm:text-xs text-slate-500">{esPeriodoActual ? `Objetivo: ${objetivo} items` : 'Próximo'}</div>
                                    <div className={`font-semibold ${esPeriodoActual ? 'text-base sm:text-lg text-slate-900' : 'text-sm text-slate-700'}`}>{esPeriodoActual ? mes : mesCorto(mes)}</div>
                                    <div className="text-xs sm:text-sm flex items-center gap-1">
                                      <span className={`font-semibold ${esPeriodoActual ? 'text-base sm:text-xl text-emerald-700' : 'text-sm text-slate-700'}`}>{completadosParaEsteMes}</span>
                                      <span className="text-slate-400">/ {objetivo}</span>
                                    </div>
                                    {esPeriodoActual && <span className="text-[11px] font-medium text-emerald-700">{Math.round(porcentajeMes)}%</span>}
                                    {esPeriodoActual && <span className="ml-2 text-[11px] font-medium text-orange-600 sm:hidden">Sin Stock {totalSinStock}</span>}
                                    {(esPeriodoActual || porcentajeMes > 0) && <Progress value={porcentajeMes} className="mt-1 h-1.5 [&>div]:bg-emerald-500" />}
                                    {esPeriodoActual && (
                                      <div className="mt-2 flex flex-wrap items-center gap-x-2 gap-y-0.5 border-t border-slate-100 pt-1.5 text-[11px] text-slate-600 sm:hidden">
                                        <span className="font-medium text-slate-500">Próximos:</span>
                                        {mesesProximos.map(({ mes: mesProximo, objetivo: objetivoProximo, completados: completadosProximo }) => (
                                          <span key={mesProximo}>{mesCorto(mesProximo)} {completadosProximo}/{objetivoProximo}</span>
                                        ))}
                                      </div>
                                    )}
                                  </>
                                )}
                              </div>
                            );
                          })}
                        </div>

                        {/* Indicador de progreso general */}
                        <div className="hidden border-y border-slate-200 py-2 sm:block" data-testid="progreso-total">
                          <div className="mb-1 flex items-center justify-between gap-2">
                            <span className="text-sm font-medium text-slate-700">Progreso de {currentCalendarMonth.toLowerCase()}</span>
                            <span className="text-sm font-semibold text-emerald-700">{totalCompletados}/{todosLosCodigos.length} · {Math.round((totalCompletados / todosLosCodigos.length) * 100)}%</span>
                          </div>
                          <Progress value={(totalCompletados / todosLosCodigos.length) * 100} className="h-1.5 [&>div]:bg-emerald-500" />
                        </div>
                        
                        {/* Barra de acciones y buscador */}
                        <div className="space-y-2.5" data-testid="acciones-checklist">
                          <div className="flex flex-wrap gap-1">
                            {([
                              { key: 'pending', label: 'Pendientes' },
                              { key: 'completed', label: 'Completados' },
                              { key: 'noStock', label: 'Sin Stock' },
                              { key: 'all', label: 'Todos' },
                            ] as { key: ChecklistViewFilter; label: string }[]).map((option) => (
                              <button
                                key={option.key}
                                type="button"
                                onClick={() => setChecklistViewFilter(option.key)}
                                className={`min-h-10 rounded-full border px-2.5 py-2 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/50 sm:px-3 sm:text-sm ${
                                  checklistViewFilter === option.key
                                    ? option.key === 'completed'
                                      ? 'border-emerald-600 bg-emerald-600 text-white'
                                      : option.key === 'noStock'
                                        ? 'border-orange-500 bg-orange-500 text-white'
                                        : 'border-slate-700 bg-slate-700 text-white'
                                    : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50'
                                }`}
                              >
                                {option.label}
                              </button>
                            ))}
                          </div>

                          <div className="hidden grid-cols-2 gap-x-3 gap-y-1.5 border-y border-slate-100 py-2 md:grid-cols-4" data-testid="resumen-checklist">
                            <div className="px-1 py-0.5">
                              <div className="text-[11px] uppercase tracking-wide text-gray-500">Pendientes</div>
                              <div className="text-xl font-bold text-gray-900">{checklistSummary.pending}</div>
                            </div>
                            <div className="px-1 py-0.5">
                              <div className="text-[11px] uppercase tracking-wide text-gray-500">Completados</div>
                              <div className="text-xl font-bold text-green-600">{checklistSummary.completed}</div>
                            </div>
                            <div className="px-1 py-0.5">
                              <div className="text-[11px] uppercase tracking-wide text-gray-500">Sin Stock</div>
                              <div className="text-xl font-bold text-orange-500">{checklistSummary.noStock}</div>
                            </div>
                            <div className="px-1 py-0.5">
                              <div className="text-[11px] uppercase tracking-wide text-gray-500">Total</div>
                              <div className="text-xl font-bold text-gray-900">{checklistSummary.total}</div>
                            </div>
                          </div>

                          <div className="rounded-md border border-slate-200 bg-white p-1.5 sm:p-2" data-testid="buscador-items">
                            <div className="relative">
                              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                              <input
                                type="text"
                                placeholder={`Buscar en ${checklistFilterLabels[checklistViewFilter].toLowerCase()}...`}
                                value={searchFilter}
                                onChange={(e) => setSearchFilter(e.target.value)}
                                className="w-full rounded-md border border-slate-200 py-2.5 pl-9 pr-9 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50"
                              />
                              {searchFilter && (
                                <button
                                  onClick={() => setSearchFilter('')}
                                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                                >
                                  <X className="h-4 w-4" />
                                </button>
                              )}
                            </div>
                            {(searchFilter || checklistViewFilter !== 'pending') && (
                              <p className="text-xs text-gray-500 mt-1">
                                {visibleChecklistEntries.length} resultados en {checklistFilterLabels[checklistViewFilter].toLowerCase()}
                              </p>
                            )}
                          </div>
                        </div>
                        </div>

                        {/* Lista de todos los items para seleccionar */}
                        <div id="items-lista" className="overflow-hidden rounded-md border border-slate-200" data-testid="items-lista">
                          <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-2.5 py-1.5 sm:py-2">
                            <div className="flex items-center gap-2">
                              <Calendar className="hidden h-4 w-4 sm:block" />
                              <span className="font-semibold sm:hidden">Familias</span>
                              <span className="hidden font-semibold sm:inline">{checklistFilterLabels[checklistViewFilter]}</span>
                            </div>
                            <span className="hidden text-xs font-semibold text-slate-700 sm:text-sm">{visibleChecklistEntries.length} visibles · {checklistSummary.completed}/{checklistSummary.total}</span>
                          </div>
                          
                          <div className="max-h-[60vh] space-y-1.5 overflow-y-auto bg-slate-50/50 p-1.5">
                            {checklistFamilies.map((group) => {
                              const total = group.allEntries.length;
                              const percentage = total > 0 ? Math.round((group.completed / total) * 100) : 0;
                              const isOpen = searchOpenFamily !== null
                                ? searchOpenFamily === group.family
                                : openChecklistFamily === group.family;
                              return (
                                <div key={group.family} className={`overflow-hidden rounded-md border ${isOpen ? 'border-primary/40 bg-primary/[0.03]' : 'border-slate-200 bg-white'}`}>
                                  <button
                                    type="button"
                                    onClick={() => setOpenChecklistFamily(isOpen ? null : group.family)}
                                    className="w-full p-2 text-left transition-colors hover:bg-slate-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary/50 sm:px-3 sm:py-2.5"
                                  >
                                    <div className="flex items-center justify-between gap-2">
                                      <span className="min-w-0 truncate font-mono text-sm font-bold">{checklistFamilyLabel[group.family]}</span>
                                      <span className="shrink-0 text-xs font-semibold">{group.completed}/{total}</span>
                                    </div>
                                    <Progress value={percentage} className="mt-1 hidden h-1 sm:block [&>div]:bg-emerald-500" />
                                    <div className="mt-1 flex items-center justify-between gap-2 text-[11px] text-slate-500">
                                      <span>{total} artículos solicitados{group.noStock > 0 ? ` · ${group.noStock} sin stock` : ''}</span>
                                      <span className="flex items-center gap-1">{percentage}% <ChevronDown className={`h-4 w-4 transition-transform ${isOpen ? 'rotate-180' : ''}`} /></span>
                                    </div>
                                  </button>
                                  {isOpen && (
                                  <div className="grid grid-cols-1 gap-1 border-t border-slate-200 bg-slate-50/60 p-1.5 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4">
                                      {group.visibleEntries.map(entry => {
                              const state = getLocalItemState(items, entry.code, entry.periodKey);
                              const isCompleted = isChecklistCompleted(state);
                              const isNoStock = isChecklistNoStock(state);
                              const itemStatusLabel = isCompleted ? 'Completado' : isNoStock ? 'Sin Stock' : 'Pendiente';
                              return (
                                <div
                                  key={getChecklistEntryKey(entry.code, entry.periodKey)}
                                  className={`flex flex-col gap-2 rounded-md border px-2 py-1.5 transition-colors sm:flex-row sm:items-center sm:justify-between ${
                                    isCompleted 
                                      ? 'border-emerald-200 bg-emerald-50/60'
                                      : isNoStock
                                        ? 'border-orange-200 bg-orange-50/60'
                                        : 'border-slate-200 bg-white hover:border-slate-300'
                                  }`}
                                >
                                  <div className="min-w-0">
                                    <span className="block font-mono text-sm font-medium text-slate-900">{entry.code}</span>
                                    {entry.description && (
                                      <span className="block break-words text-[11px] leading-tight text-slate-500">{entry.description}</span>
                                    )}
                                    {entry.sinAjuste1A && (
                                      <span className="mt-1 inline-flex w-fit rounded border border-amber-200 bg-amber-50 px-1.5 py-0.5 text-[10px] font-medium leading-tight text-amber-800">Sin ajuste +1 año</span>
                                    )}
                                    <span className={`hidden text-[11px] font-medium sm:block ${
                                      isCompleted ? 'text-emerald-700' : isNoStock ? 'text-orange-700' : 'text-slate-500'
                                    }`}>
                                      {itemStatusLabel}
                                    </span>
                                  </div>
                                  <div className="flex w-full shrink-0 gap-1 text-[11px] sm:w-auto sm:flex-col sm:text-[10px]">
                                    <label className="flex min-h-11 flex-1 items-center justify-center gap-1 rounded border border-emerald-100 px-2 text-emerald-700 sm:min-h-0 sm:justify-start sm:border-0 sm:px-0">
                                      <Checkbox
                                        checked={isCompleted}
                                        onCheckedChange={() => handleToggle(entry.code, 'completed', entry.periodKey)}
                                        disabled={loading || isFirebaseReadOnly}
                                        className="h-4 w-4"
                                      />
                                      <span>Completado</span>
                                    </label>
                                    <label className="flex min-h-11 flex-1 items-center justify-center gap-1 rounded border border-orange-100 px-2 text-orange-700 sm:min-h-0 sm:justify-start sm:border-0 sm:px-0">
                                      <Checkbox
                                        checked={isNoStock}
                                        onCheckedChange={() => handleToggle(entry.code, 'hasStock', entry.periodKey)}
                                        disabled={loading || isFirebaseReadOnly}
                                        className="h-4 w-4"
                                      />
                                      <span>Sin Stock</span>
                                    </label>
                                  </div>
                                </div>
                              );
                                      })}
                                      {group.visibleEntries.length === 0 && <p className="p-2 text-xs text-gray-500">Sin artículos para este filtro.</p>}
                                    </div>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      </>
                    );
                  })()}
                </div>
              )}

              {/* Sección Items Agregados */}
              <div className="border-2 border-dashed border-blue-300 rounded-lg overflow-hidden" data-testid="items-agregados">
                <div className="bg-blue-100 dark:bg-blue-900/30 px-2 py-2 sm:p-3 flex items-center justify-between gap-1">
                  <div className="flex items-center gap-1.5 sm:gap-2 min-w-0">
                    <Plus className="h-4 w-4 text-blue-600 shrink-0" />
                    <span className="font-semibold text-sm sm:text-base text-blue-800 dark:text-blue-200 truncate">Items Agregados</span>
                  </div>
                  <span className="text-xs sm:text-sm font-bold text-blue-600 whitespace-nowrap">{Object.keys(currentMonthAddedItems).length} ({new Date().toLocaleString('es-AR', { month: 'short' })})</span>
                </div>
                <div className="p-2 sm:p-3 space-y-2 sm:space-y-3">
                  <div className="flex gap-1.5 sm:gap-2">
                    <input
                      type="text"
                      placeholder="Código artículo..."
                      value={newItemCode}
                      onChange={(e) => setNewItemCode(e.target.value)}
                      onKeyDown={(e) => { if (e.key === 'Enter') handleAddItem(); }}
                      className="flex-1 min-w-0 px-2 sm:px-3 py-2 border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50"
                    />
                    <Button size="sm" onClick={handleAddItem} disabled={isFirebaseReadOnly || !newItemCode.trim()} className="shrink-0 gap-1 bg-blue-600 hover:bg-blue-700 px-2 sm:px-3">
                      <Plus className="h-4 w-4" />
                      <span className="hidden sm:inline">Agregar</span>
                    </Button>
                  </div>
                  {Object.keys(currentMonthAddedItems).length > 0 && (
                    <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-1">
                      {Object.entries(currentMonthAddedItems).map(([key, item]) => (
                        <div
                          key={key}
                          className="flex items-center justify-between p-1.5 sm:p-2 rounded bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800"
                        >
                          <span className="font-mono text-xs sm:text-sm text-blue-800 dark:text-blue-200 truncate mr-1">{item.code}</span>
                          <button
                            onClick={() => handleRemoveAddedItem(key)}
                            className="text-red-400 hover:text-red-600 transition-colors p-0.5 sm:p-1 shrink-0"
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                  {Object.keys(currentMonthAddedItems).length === 0 && (
                    <p className="text-xs text-gray-500 text-center py-2">No hay items agregados este mes. Usá el campo de arriba para agregar artículos que encuentres de más.</p>
                  )}
                </div>
              </div>

            </CardContent>
          </Card>
          {showScrollButton && (
            <Button
              variant="outline"
              size="icon"
              className="fixed bottom-4 right-4 rounded-full shadow-lg hover:shadow-xl transition-all duration-300 bg-primary/10 hover:bg-primary/20 border-primary/20 hover:border-primary/30 h-12 w-12 hover:scale-110"
              onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
            >
              <ArrowUp className="h-6 w-6 text-primary animate-bounce" />
            </Button>
          )}
        </div>
      ) : (
        <Dashboard onBranchSelect={(branch: string) => loadBranchData(branch as Branch)} />
      )}
    </div>
  );
}
